    {
      "target_ids": ["a10", "n02"],
      "unresolved_question": "How representative and variable is the 1700 h retention comparison across devices?",
      "needed_observations": [
        "The number of devices measured per paste and device-level PCE retention values or group summaries with uncertainty over time."
      ],
      "comparison_or_control": "Unencapsulated control, SiC, and SiC-APTES devices stored and measured under the same conditions.",
      "why_informative": "Replicate counts and dispersion would clarify the strength and variability of the reported group comparison.",
      "missing_design_information": [
        "The visible main-text record does not state the number of devices in the stability comparison."
      ]
    }
  ],
  "preserved_ids": ["a03", "a10", "n02", "d15", "i09"],
  "information_requests": [
    "Provide the measured Rs and Rsh results and the additive-loading-series outcomes if those endpoints or loading dependence are to be assessed from visible results.",
    "Provide the stability-test device counts and device-level or group-level uncertainty to assess the representativeness of the retention comparison."
